CREATE SCHEMA IF NOT EXISTS "public";
CREATE TYPE "SyncStatus" AS ENUM ('RUNNING', 'SUCCESS', 'PARTIAL', 'FAILED');
CREATE TYPE "TableArea" AS ENUM ('TABLE', 'BAR');
CREATE TYPE "AnalyticsEventType" AS ENUM ('PAGE_VIEW', 'MENU_VIEW', 'PRODUCT_VIEW', 'WHATSAPP_CART');

CREATE TABLE "Admin" ("id" TEXT NOT NULL, "email" TEXT NOT NULL, "passwordHash" TEXT NOT NULL, "active" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Admin_pkey" PRIMARY KEY ("id"));
CREATE TABLE "AdminSession" ("id" TEXT NOT NULL, "tokenHash" TEXT NOT NULL, "adminId" TEXT NOT NULL, "expiresAt" TIMESTAMP(3) NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "lastSeenAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "AdminSession_pkey" PRIMARY KEY ("id"));
CREATE TABLE "AppConfig" ("id" TEXT NOT NULL DEFAULT 'default', "publicName" TEXT, "publicDescription" TEXT, "logoUrl" TEXT, "contactPhone" TEXT, "showObservedDiscounts" BOOLEAN NOT NULL DEFAULT false, "observedDiscountMaxAgeHours" INTEGER NOT NULL DEFAULT 72, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "AppConfig_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Category" ("id" TEXT NOT NULL, "externalId" INTEGER NOT NULL, "branchId" INTEGER NOT NULL, "name" TEXT NOT NULL, "description" TEXT, "active" BOOLEAN NOT NULL DEFAULT true, "syncedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Category_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Product" ("id" TEXT NOT NULL, "externalId" INTEGER NOT NULL, "branchId" INTEGER NOT NULL, "code" TEXT, "name" TEXT NOT NULL, "menuDescription" TEXT, "longDescription" TEXT, "price" DECIMAL(12,2) NOT NULL, "categoryId" TEXT, "sourceCategoryId" INTEGER, "active" BOOLEAN NOT NULL DEFAULT true, "lastValidSyncAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Product_pkey" PRIMARY KEY ("id"));
CREATE TABLE "OptionGroup" ("id" TEXT NOT NULL, "externalId" INTEGER NOT NULL, "productId" TEXT NOT NULL, "name" TEXT NOT NULL, "required" BOOLEAN NOT NULL DEFAULT false, CONSTRAINT "OptionGroup_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ProductVariant" ("id" TEXT NOT NULL, "externalId" INTEGER NOT NULL, "optionGroupId" TEXT NOT NULL, "name" TEXT NOT NULL, "priceDelta" DECIMAL(12,2) NOT NULL, CONSTRAINT "ProductVariant_pkey" PRIMARY KEY ("id"));
CREATE TABLE "PriceHistory" ("id" TEXT NOT NULL, "productId" TEXT NOT NULL, "price" DECIMAL(12,2) NOT NULL, "previousPrice" DECIMAL(12,2), "isPriceDecrease" BOOLEAN NOT NULL DEFAULT false, "reductionPercent" DECIMAL(7,4), "observedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "syncRunId" TEXT, CONSTRAINT "PriceHistory_pkey" PRIMARY KEY ("id"));
CREATE TABLE "OfferConfig" ("id" TEXT NOT NULL DEFAULT 'default', "enabled" BOOLEAN NOT NULL DEFAULT false, "maxObservationAgeHours" INTEGER NOT NULL DEFAULT 72, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "OfferConfig_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Advertisement" ("id" TEXT NOT NULL, "title" TEXT NOT NULL, "imageUrl" TEXT, "targetUrl" TEXT, "active" BOOLEAN NOT NULL DEFAULT false, "startsAt" TIMESTAMP(3), "endsAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Advertisement_pkey" PRIMARY KEY ("id"));
CREATE TABLE "BusinessHours" ("id" TEXT NOT NULL, "dayOfWeek" INTEGER NOT NULL, "opensAt" TEXT, "closesAt" TEXT, "closed" BOOLEAN NOT NULL DEFAULT false, CONSTRAINT "BusinessHours_pkey" PRIMARY KEY ("id"));
CREATE TABLE "VenueTable" ("id" TEXT NOT NULL, "code" TEXT NOT NULL, "label" TEXT NOT NULL, "area" "TableArea" NOT NULL, "active" BOOLEAN NOT NULL DEFAULT true, CONSTRAINT "VenueTable_pkey" PRIMARY KEY ("id"));
CREATE TABLE "QrIdentifier" ("id" TEXT NOT NULL, "token" TEXT NOT NULL, "tableId" TEXT, "active" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "QrIdentifier_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ComplementaryGoodRule" ("id" TEXT NOT NULL, "productExternalId" INTEGER NOT NULL, "complementaryExternalId" INTEGER NOT NULL, "active" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "ComplementaryGoodRule_pkey" PRIMARY KEY ("id"));
CREATE TABLE "AnalyticsEvent" ("id" TEXT NOT NULL, "type" "AnalyticsEventType" NOT NULL, "path" TEXT, "productId" TEXT, "metadata" JSONB, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "AnalyticsEvent_pkey" PRIMARY KEY ("id"));
CREATE TABLE "PreparedCart" ("id" TEXT NOT NULL, "productId" TEXT, "payload" JSONB NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "expiresAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "PreparedCart_pkey" PRIMARY KEY ("id"));
CREATE TABLE "SyncRun" ("id" TEXT NOT NULL, "status" "SyncStatus" NOT NULL DEFAULT 'RUNNING', "branchId" INTEGER NOT NULL, "startedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "completedAt" TIMESTAMP(3), "categoryCount" INTEGER NOT NULL DEFAULT 0, "productCount" INTEGER NOT NULL DEFAULT 0, "errorCode" TEXT, "errorMessage" TEXT, CONSTRAINT "SyncRun_pkey" PRIMARY KEY ("id"));
CREATE TABLE "SyncLock" ("id" TEXT NOT NULL, "lockedUntil" TIMESTAMP(3) NOT NULL, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "SyncLock_pkey" PRIMARY KEY ("id"));
CREATE TABLE "AdminAuditLog" ("id" TEXT NOT NULL, "adminId" TEXT NOT NULL, "action" TEXT NOT NULL, "entity" TEXT NOT NULL, "entityId" TEXT, "metadata" JSONB, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "AdminAuditLog_pkey" PRIMARY KEY ("id"));

CREATE UNIQUE INDEX "Admin_email_key" ON "Admin"("email");
CREATE UNIQUE INDEX "AdminSession_tokenHash_key" ON "AdminSession"("tokenHash");
CREATE INDEX "AdminSession_adminId_expiresAt_idx" ON "AdminSession"("adminId", "expiresAt");
CREATE UNIQUE INDEX "Category_externalId_branchId_key" ON "Category"("externalId", "branchId");
CREATE INDEX "Category_branchId_active_idx" ON "Category"("branchId", "active");
CREATE UNIQUE INDEX "Product_externalId_branchId_key" ON "Product"("externalId", "branchId");
CREATE INDEX "Product_categoryId_active_idx" ON "Product"("categoryId", "active");
CREATE UNIQUE INDEX "OptionGroup_productId_externalId_key" ON "OptionGroup"("productId", "externalId");
CREATE UNIQUE INDEX "ProductVariant_optionGroupId_externalId_key" ON "ProductVariant"("optionGroupId", "externalId");
CREATE INDEX "PriceHistory_productId_observedAt_idx" ON "PriceHistory"("productId", "observedAt");
CREATE UNIQUE INDEX "BusinessHours_dayOfWeek_key" ON "BusinessHours"("dayOfWeek");
CREATE UNIQUE INDEX "VenueTable_code_key" ON "VenueTable"("code");
CREATE UNIQUE INDEX "QrIdentifier_token_key" ON "QrIdentifier"("token");
CREATE UNIQUE INDEX "QrIdentifier_tableId_key" ON "QrIdentifier"("tableId");
CREATE UNIQUE INDEX "ComplementaryGoodRule_productExternalId_complementaryExtern_key" ON "ComplementaryGoodRule"("productExternalId", "complementaryExternalId");
CREATE INDEX "AnalyticsEvent_type_createdAt_idx" ON "AnalyticsEvent"("type", "createdAt");
CREATE INDEX "PreparedCart_expiresAt_idx" ON "PreparedCart"("expiresAt");
CREATE INDEX "SyncRun_branchId_startedAt_idx" ON "SyncRun"("branchId", "startedAt");
CREATE INDEX "AdminAuditLog_adminId_createdAt_idx" ON "AdminAuditLog"("adminId", "createdAt");

ALTER TABLE "AdminSession" ADD CONSTRAINT "AdminSession_adminId_fkey" FOREIGN KEY ("adminId") REFERENCES "Admin"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Product" ADD CONSTRAINT "Product_categoryId_fkey" FOREIGN KEY ("categoryId") REFERENCES "Category"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "OptionGroup" ADD CONSTRAINT "OptionGroup_productId_fkey" FOREIGN KEY ("productId") REFERENCES "Product"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "ProductVariant" ADD CONSTRAINT "ProductVariant_optionGroupId_fkey" FOREIGN KEY ("optionGroupId") REFERENCES "OptionGroup"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "PriceHistory" ADD CONSTRAINT "PriceHistory_productId_fkey" FOREIGN KEY ("productId") REFERENCES "Product"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "PriceHistory" ADD CONSTRAINT "PriceHistory_syncRunId_fkey" FOREIGN KEY ("syncRunId") REFERENCES "SyncRun"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "QrIdentifier" ADD CONSTRAINT "QrIdentifier_tableId_fkey" FOREIGN KEY ("tableId") REFERENCES "VenueTable"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "PreparedCart" ADD CONSTRAINT "PreparedCart_productId_fkey" FOREIGN KEY ("productId") REFERENCES "Product"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "AdminAuditLog" ADD CONSTRAINT "AdminAuditLog_adminId_fkey" FOREIGN KEY ("adminId") REFERENCES "Admin"("id") ON DELETE CASCADE ON UPDATE CASCADE;
